    ]);
    let cases = [
        (r#""QueueName": "q", "Body": "b", "DeduplicationId": "d""#, "UnsupportedOperation"),
        (r#""QueueName": "f.fifo", "Body": "b", "DelaySeconds": 0"#, "UnsupportedOperation"),
        (r#""QueueName": "f.fifo", "Body": "b", "DeduplicationId": "d""#, "MissingParameter"),
        (r#""QueueName": "f.fifo", "Body": "b", "GroupId": "g""#, "MissingParameter"),
