    for (members, code) in cases {
        let line = format!(r#"{{"Command": "SendMessage", {members}}}"#);
        assert_eq!(s.call(&line), err(code), "members {members}");
    }
    assert_eq!(
        s.call(r#"{"Command": "SendMessage", "QueueName": "f.fifo", "Body": "b", "GroupId": "g", "DeduplicationId": "d"}"#),
