    tick(&mut s, 2);
    assert_eq!(
        receive(&mut s, "q", 10),
        json!({"ok": true, "Messages": [{
            "MessageId": "m-1",
            "ReceiptHandle": "r-1",
            "Body": "hello",
            "ReceiveCount": 1,
            "SentAt": 3,
            "FirstReceivedAt": 5,
        }]})
    );
    assert_eq!(receive(&mut s, "q", 10), json!({"ok": true, "Messages": []}));
}

