#[test]
fn change_message_visibility_restarts_the_timeout_from_now() {
    let mut s = standard();
    send(&mut s, "q", "a");
    receive(&mut s, "q", 1);
    tick(&mut s, 20);
    s.ok(r#"{"Command": "ChangeMessageVisibility", "QueueName": "q", "ReceiptHandle": "r-1", "VisibilityTimeout": 100}"#);
    tick(&mut s, 99);
