    // The id ignores the group and outlives the message.
    receive(&mut s, "f.fifo", 1);
    delete(&mut s, "f.fifo", "r-1");
    tick(&mut s, 299);
    assert_eq!(send_group(&mut s, "same", "other"), json!({"ok": true, "MessageId": "m-1", "SequenceNumber": 1}));
